def solve():
    N = 13
    s = [0] * N
    occ = [0] * (N + 2)  # up to 14+
    fixed = {7: 0, 11: 0}
    forbidden = {7, 11}  # cannot place these values

    def bt(pos):
        if pos == N:
            return True
        if pos in fixed:
            vals = [fixed[pos]]
        else:
            vals = list(range(0, N + 1))  # 0 to 13
        for v in vals:
            if v in forbidden:
                continue
            occ[v] += 1
            can = True
            remaining = N - pos - 1
            for k in range(pos + 1):  # all k <= pos have s[k] set
                target = s[k]
                cur = occ[k]
                if cur > target or (cur + remaining < target):
                    can = False
                    break
            if can:
                s[pos] = v
                if bt(pos + 1):
                    return True
            occ[v] -= 1
        return False

    if bt(0):
        return s
    else:
        return "UNSATISFIABLE"

