def is_safe(board, row, col, n):
    for i in range(row):
        if board[i] == col:
            return False
        if board[i] - i == col - row:
            return False
        if board[i] + i == col + row:
            return False
    return True

def solve_nqueens_util(board, row, n, fixed):
    if row == n:
        return True
    if row in fixed:
        col = fixed[row]
        if col < 0 or col >= n or not is_safe(board, row, col, n):
            return False
        board[row] = col
        if solve_nqueens_util(board, row + 1, n, fixed):
            return True
        board[row] = -1
        return False
    for col in range(n):
        if is_safe(board, row, col, n):
            board[row] = col
            if solve_nqueens_util(board, row + 1, n, fixed):
                return True
            board[row] = -1
    return False

def solve_nqueens(n, fixed):
    board = [-1] * n
    if solve_nqueens_util(board, 0, n, fixed):
        return board
    return None

n = 22
fixed = {11:8, 16:14, 18:11, 21:13}
solution = solve_nqueens(n, fixed)
print(solution)
